function offSummaryFallback(ended,c,plan){const rows=(ended.msgs||[]).filter(m=>m&&m.who!=='日期'&&m.who!=='旁白'&&String(m.text||'').trim()),take=Math.min(rows.length,plan.level==='完整长篇'?16:plan.level==='详细'?12:plan.level==='适中'?8:5),picks=[];for(let i=0;i<take;i++){const at=take===1?0:Math.round(i*(rows.length-1)/(take-1)),m=rows[at];if(m&&!picks.includes(m))picks.push(m);}const details=picks.map(m=>{const who=m.who==='me'?S.me.name+'对我说':'我当时说';return who+'：「'+String(m.text||'').replace(/\s+/g,' ').slice(0,100)+'」';}).filter(Boolean).join('；');return trimSentence('我和'+S.me.name+'在「'+(ended.loc||'约定地点')+'」见面，那时是'+(ended.daypart||ended.when||'约定的时间')+'。'+(details?'我从自己的角度记得这些重要话语：'+details+'。':'我记得我们完成了这次见面。'),plan.keep);}
async function offSummarySinglePoint(c,ended,plan,useAux,retry){const prepared=await offSummaryPreparedText(c,ended,offSummaryTranscript(ended,c),useAux),call=offSummaryUserCall(c),min=plan.level==='简短'?140:plan.level==='适中'?260:plan.level==='详细'?480:700,max=Math.min(1800,Math.max(min+140,plan.keep));let prompt='你就是「'+(c.remark||c.name)+'」本人。把这整场线下约会整理成【一条连续、完整的第一人称长期记忆】，约'+min+'~'+max+'个中文字。必须从见面开场写到最后分别，按真实发生顺序自然串起真正重要的事件、双方重要问答、'+call+'透露的信息、承诺约定、关系或情绪变化及最终结果。普通动作、环境和姿势不写入记忆。只依据原记录，不补写原文没有的心理、原因、承诺或结局。'+offSummaryPerspectiveRule(c)+'\n全文只能是一整段：不分段、不列点、不写标题、编号或JSON，也不要提AI和规则。';if(retry)prompt+=' 上一版不够完整，请重新核对开头、转折和最后几条，避免遗漏。';let raw=await chatAPI([{role:'system',content:prompt+perspRule(c)},{role:'user',content:prepared.text}],{aux:useAux,max:Math.min(2600,plan.tokens+500),temp:.16}),text=trimSentence(cleanReply(raw).replace(/\s*\n+\s*/g,' ').replace(/\s{2,}/g,' ').trim(),max);if(isRefusal(text)||Array.from(text).length<100||!offSummaryMemoryPerspectiveValid(text))throw new Error('模型没有返回完整的角色第一人称整场总结');return{text,importance:4,indexes:[]};}
function offSummaryDate(ended){const w=String(ended&&ended.when||''),m=w.match(/(\d{4})[-\/.\u5e74](\d{1,2})[-\/.\u6708](\d{1,2})/);if(m)return(+m[1])+'年'+(+m[2])+'月'+(+m[3])+'日';const d=new Date(+ended.startedAt||Date.now());return d.getFullYear()+'年'+(d.getMonth()+1)+'月'+d.getDate()+'日';}
function offSummaryPointImp(text,n){if(n!=null&&n!=='')return Math.max(1,Math.min(5,parseInt(n,10)||3));text=String(text||'');if(/永远|一辈子|结婚|求婚|订婚|分手|复合|重大承诺|生命/.test(text))return 5;if(/承诺|约定|和好|争执|告白|哭|分别|送别|关系/.test(text))return 4;return 3;}
function offSummarySplitPoints(text,plan){const rows=String(text||'').replace(/\r/g,'').replace(/([。！？!?])/g,'$1\n').split(/\n+/).map(x=>x.replace(/^\s*(?:[-*·]|\d+[.、])\s*/,'').trim()).filter(x=>x.length>=8),out=[];let cur='';for(const row of rows){if(cur&&(cur.length>=55||cur.length+row.length>180)){out.push(cur);cur=row;}else cur+=row;}if(cur)out.push(cur);const max=plan&&plan.maxPoints||8;return out.slice(0,max).map(text=>({text:trimSentence(text,220),importance:offSummaryPointImp(text)}));}
function offSummaryQuote(text){const a=Array.from(String(text||'').replace(/\s+/g,' ').trim()),cut=a.slice(0,160).join('');return cut+(a.length>160?'…':'');}
function offSummaryExpandedIndexes(ended,indexes){const rows=offSummarySourceRows(ended),core=[...new Set((indexes||[]).map(x=>parseInt(x,10)).filter(x=>x>=1&&x<=rows.length))].sort((a,b)=>a-b).slice(0,6);if(!core.length)return[];const set=new Set(core);let left=core[0]-1,right=core[core.length-1]+1,chars=core.reduce((n,i)=>n+Array.from(String(rows[i-1].text||'')).length,0);while(chars<180&&set.size<8&&(left>=1||right<=rows.length)){if(left>=1){set.add(left);chars+=Array.from(String(rows[left-1].text||'')).length;left--;}if(chars>=180||set.size>=8)break;if(right<=rows.length){set.add(right);chars+=Array.from(String(rows[right-1].text||'')).length;right++;}}return[...set].sort((a,b)=>a-b);}
