function rpData(id){S.roleplay=S.roleplay||{};if(!S.roleplay[id])S.roleplay[id]={active:false,title:'',date:todayStr(),time:'20:30',daypart:'晚上',plot:'',scene:'',myRole:'',hisRole:'',myPersona:'',hisPersona:'',msgs:[],memory:[],startedAt:0,inviteMid:'',summary:''};return S.roleplay[id];}
function rpWhenText(d){return [d.date||'',d.time||'',d.daypart||''].filter(Boolean).join(' · ');}
function rpStatusText(d){return d.active?('进行中 · '+(d.title||'本次剧情')):((d.memory&&d.memory.length)?('已有 '+d.memory.length+' 条存档'):'还没开局');}
