function rpMembers(id){const d=rpData(id);let arr=Array.isArray(d.members)?d.members.slice():[];if(!arr.some(x=>x.id===id))arr.unshift({id:id,role:d.hisRole||'',persona:d.hisPersona||'',lead:true});arr=arr.filter(x=>x&&x.id&&getC(x.id)&&!getC(x.id).deleted);arr.forEach((x,i)=>{if(x.id===id){x.lead=true;x.role=d.hisRole||x.role||'';x.persona=d.hisPersona||x.persona||'';}else x.lead=false;});return arr;}
function rpMemberTitle(m){const c=getC(m.id);return ((c&&(c.remark||c.name))||'角色')+(m.role?(' / '+m.role):'');}
function rpMemberSummary(id){return rpMembers(id).map(m=>rpMemberTitle(m)).join('、');}
