function rpStudioHelp(){rpStudioModal('<h3>独立剧情工作室</h3><div class="rp-studio-help"><p>在这里给角色配置本局身份、剧情背景、开场和日期，也可以邀请其他已有角色一起参演。</p><p>这些临时设定只在这局角色扮演里生效，不会覆盖微信中的原有人设和关系。</p><p>“继续剧情”会回到原来的对话；“剧情存档”里分“存档”和“总结”两页。结束本局并确认后才整理存档，刷新和返回不会结束剧情。</p><p>一个角色可以有多个存档：“新开一局”不会结束正在玩的那局，它会留在“剧情存档 → 存档”里，随时读取接着玩。“剧情存档 → 总结”是角色记得的记忆，两页分开。</p></div><button class="btn p" onclick="closeModal()">知道了</button>');}
function rpStudioMore(id){const c=getC(id);if(!c)return;const d=rpData(id),j=rpStudioId(id);rpStudioModal(`<h3>${esc(c.remark||c.name)}</h3><div class="rp-studio-menu"><button class="btn g" onclick="closeModal();go('rpset',${d.active?`{id:${j}}`:`{id:${j},fresh:true}`})">${d.active?'修改本局配置':'配置开局'}</button>${d.active?`<button class="btn g" onclick="rpNewGame(${j})">新开一局（这局自动存档）</button>`:''}<button class="btn g" onclick="rpMemory(${j})">查看剧情存档</button>${d.active?`<button class="btn d" onclick="closeModal();rpEnd(${j})">结束本局并存档</button>`:''}</div><button class="btn g" onclick="closeModal()">取消</button>`);}
