function rpStudioCat(){const head='<path d="M4 22C4 17 6 13 10 11L9 3Q9 1 11 3L20 9Q26 7 32 9L41 3Q43 1 42 4L40 14Q44 18 44 24C44 33 36 37 24 37S4 33 4 22Z"/><path d="m13 10-1-4 5 5m18 0 5-5-1 7"/>';return '<svg viewBox="0 0 96 40" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><g>'+head+'<circle cx="16" cy="22" r="1.4" fill="currentColor" stroke="none"/><circle cx="33" cy="22" r="1.4" fill="currentColor" stroke="none"/><path d="M19 27q2 4 5 0 3 4 5 0"/><path d="M11 27h2m23 0h2"/></g><g transform="translate(48 0)">'+head+'<path d="m14 22 3-2 3 2m9 0 3-2 3 2M20 30q4-5 8 0"/><path d="M11 27h2m23 0h2"/></g></svg>';}
function rpStudioAvatarFrame(){return '<svg class="rp-avatar-outline" viewBox="0 0 100 116" preserveAspectRatio="none" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M1 28Q1 14 13 14L17 3Q18 0 21 3L34 14H66L79 3Q82 0 83 3L87 14Q99 14 99 28V101Q99 115 85 115H15Q1 115 1 101Z"/><path d="m18 11 2-5 7 6m46 0 7-6 2 5"/></svg>';}
function renderRPHub(){S.roleplay=S.roleplay||{};const cs=S.contacts.filter(c=>!c.deleted),query=_rpStudioSearch.trim().toLowerCase(),active=cs.filter(c=>rpData(c.id).active).sort((a,b)=>(+rpData(b.id).startedAt||0)-(+rpData(a.id).startedAt||0)),matches=c=>!query||[c.name,c.remark,rpData(c.id).title].join(' ').toLowerCase().includes(query),visible=cs.filter(c=>matches(c)&&(_rpStudioFilter==='all'||!!rpData(c.id).active===(_rpStudioFilter==='active'))),featured=active.find(c=>visible.some(x=>x.id===c.id)),others=visible.filter(c=>!featured||c.id!==featured.id);
 const avatar=(c,large)=>`<span class="rp-cat-avatar ${large?'large':''}">${av(c.avatar,'sm')}${rpStudioAvatarFrame()}</span>`;
 const row=c=>{const d=rpData(c.id),j=rpStudioId(c.id),n=rpPaused(c.id).length;return `<article class="rp-studio-row" data-rp-role="${rpStudioAttr(c.id)}"><button class="rp-role-main" onclick="rpOpen(${j})">${avatar(c,false)}<span><b>${esc(c.remark||c.name)}</b><small>${esc((d.active?(d.title||'剧情进行中'):(n?'':'还没开局'))+(n?(d.active?' · 另有 ':'')+n+' 个存档':''))}</small></span></button><button class="rp-pink rp-row-start" onclick="rpOpen(${j})">${d.active?'继续剧情':n?'读取存档':'配置开局'}</button><button class="rp-outline rp-row-archive" onclick="rpMemory(${j})">剧情存档</button><button class="rp-row-more" aria-label="${rpStudioAttr(c.remark||c.name)}更多操作" onclick="rpStudioMore(${j})">···</button><button class="rp-row-arrow" aria-label="打开${rpStudioAttr(c.remark||c.name)}剧情" onclick="rpOpen(${j})">›</button></article>`;};
 const feature=featured?(()=>{const d=rpData(featured.id),j=rpStudioId(featured.id);return `<section class="rp-feature" data-rp-feature="${rpStudioAttr(featured.id)}"><button class="rp-feature-more" aria-label="当前剧情更多操作" onclick="rpStudioMore(${j})">···</button><div class="rp-feature-top">${avatar(featured,true)}<div><h2>${esc(featured.remark||featured.name)}</h2><div class="rp-feature-status"><span>${rpStudioPaw()}</span> 进行中</div><p>${esc(d.title||'本次剧情')}</p><small>已记录 ${Array.isArray(d.msgs)?d.msgs.length:0} 条 · ${esc(d.time||'')}${rpPaused(featured.id).length?' · 另有 '+rpPaused(featured.id).length+' 个存档':''}</small></div></div><div class="rp-feature-rule"></div><div class="rp-feature-actions"><button class="rp-pink" onclick="rpOpen(${j})">继续剧情</button><button class="rp-outline" onclick="rpMemory(${j})">剧情存档</button></div></section>`;})():'';
 const tab=(key,label,n)=>`<button class="${_rpStudioFilter===key?'on':''}" aria-pressed="${_rpStudioFilter===key}" onclick="rpStudioFilterSet('${key}')">${key==='all'?'<span class="rp-studio-paw">'+rpStudioPaw()+'</span> ':''}${label} ${n}</button>`;
 return `<div class="roleplay-studio"><div class="nav rp-studio-nav"><button class="l" aria-label="返回" onclick="home()">‹</button><div class="t"><b>角色扮演</b><small>CAT STORY STUDIO</small></div><button class="r rp-studio-refresh" aria-label="刷新剧情状态" onclick="rpStudioRefresh()">${svgIc('refresh',21,'currentColor')}</button></div><div class="rp-studio-scroll"><button class="rp-studio-info" onclick="rpStudioHelp()">${rpStudioCat()}<span>独立剧情不会改动微信中的原设</span><b>查看说明 ›</b></button>${feature}<label class="rp-studio-search"><svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M6 9L7 2L12 6M16 6L21 2L22 9"/><circle cx="14" cy="16" r="10.5"/><path d="M22 24L29 31"/></svg><input id="rp_studio_search" type="search" placeholder="搜索角色" aria-label="搜索角色" value="${rpStudioAttr(_rpStudioSearch)}" oninput="rpStudioSearch(this.value)"></label><div class="rp-studio-tabs">${tab('all','全部',cs.length)}${tab('active','进行中',active.length)}${tab('ready','未开局',cs.length-active.length)}</div><h3 class="rp-studio-heading">选择角色</h3>${others.map(row).join('')||`<div class="rp-studio-empty">${!cs.length?'要先有一个角色，才能邀请他进入剧情。':featured?'当前进行中的剧情在上方。':'没有符合条件的角色。'}${!cs.length?'<button class="rp-pink" onclick="openWeChat()">去微信新建角色</button>':''}</div>`}</div></div>`;}
function rpOpen(id){const d=rpData(id);if(d.active){_rp={id:id,busy:false};go('rp',{id:id});}else if(rpPaused(id).length)rpMemory(id,'saves');else go('rpset',{id:id,fresh:true});}
/* ROLEPLAY_SAVE_SLOTS_V1：一个角色可以有多局剧情（多存档）。正在玩的一局仍放在 rpData(id) 本身，
   所以聊天、总结、结束都照原样工作；暂停的局和结束的局整局（原文、本局设定、总结进度）收进 d.saves。
   「存档」管一局局的聊天，「总结」管记忆（d.memory 和角色记忆总结），两者分开，记忆位置不变。 */
function rpSlotKeys(){return ['active','title','date','time','daypart','plot','scene','myRole','hisRole','myPersona','hisPersona','advancePlot','members','msgs','startedAt','endedAt','session','summaryCursor','summary','inviteMid','inviteMids','endNotified','saveId'];}
function rpSaves(id){const d=rpData(id);if(!Array.isArray(d.saves))d.saves=[];return d.saves;}
function rpPaused(id){return rpSaves(id).filter(s=>s&&!s.ended);}
function rpSlotClear(d){Object.assign(d,{active:false,title:'',date:'',time:'20:30',daypart:'晚上',plot:'',scene:'',myRole:'',hisRole:'',myPersona:'',hisPersona:'',advancePlot:false,members:[],msgs:[],startedAt:0,endedAt:0,session:'',summaryCursor:0,summary:'',inviteMid:'',inviteMids:{}});delete d.saveId;delete d.endNotified;}
function rpSlotTake(d,extra){const slot=Object.assign({savedAt:Date.now()},extra||{});if(!d.saveId)d.saveId=uid();rpSlotKeys().forEach(k=>{if(d[k]!==undefined)slot[k]=d[k];});return slot;}
/* 换局前先把这局还没存进记忆的部分存一次（和顶上「总结」同一套：只存上次之后的新内容，不结束这局） */
function rpSaveProgressRecord(id){const d=rpData(id),list=d.msgs||[],from=Math.max(0,Math.min(list.length,+d.summaryCursor||0)),part=list.slice(from);if(!offSummarySourceRows({msgs:part}).length)return null;const rec=rpArchiveRecord(id,false);if(!rec)return null;rec.msgs=rpArchiveRows({msgs:part});rec.summary=part.map(m=>m.text).join('；').slice(0,700);d.summaryCursor=list.length;rpSyncArchive(id,rec);return rec;}
function rpParkCurrent(id){const d=rpData(id);if(!d.active||!(d.msgs||[]).length)return null;const rec=rpSaveProgressRecord(id),slot=rpSlotTake(d);rpSaves(id).unshift(slot);rpSlotClear(d);return {slot,rec};}
/* 结束后整局聊天留在「存档」页的「已结束」里，只能查看；记忆照旧在「总结」页 */
function rpParkEnded(id){const d=rpData(id);if(!(d.msgs||[]).length)return null;const slot=rpSlotTake(d,{ended:true});slot.active=false;rpSaves(id).unshift(slot);rpSlotClear(d);return slot;}
async function rpLoadSave(id,saveId){if(_rp&&_rp.busy){toast('等这一轮说完再换存档');return;}const d=rpData(id),state=S,list=rpSaves(id);if(!list.some(s=>s&&!s.ended&&s.saveId===saveId)){toast('这个存档找不到了');rpMemory(id,'saves');return;}
  const parked=rpParkCurrent(id),i=list.findIndex(s=>s&&!s.ended&&s.saveId===saveId),slot=list.splice(i,1)[0];rpSlotClear(d);rpSlotKeys().forEach(k=>{if(slot[k]!==undefined)d[k]=slot[k];});d.active=true;d.endedAt=0;if(!Array.isArray(d.msgs))d.msgs=[];
  _rp={id:id,busy:false};_rpSel=null;closeModal();if(!await saveNowAsync())toast('已换到这局，但写入失败，请稍后再试');if(S!==state)return;go('rp',{id:id});if(parked&&parked.rec)rpSummarizeArchive(id,parked.rec.id);}
