  if(S!==owner||actId()!==account||!!d.active!==wasActive||d.startedAt!==oldStart)return null;if(wasActive&&rpInviteKeepsCurrent(id))return rpPushInviteMsg(id,'assistant');let parked=null;if(d.active)parked=rpParkCurrent(id);else if(d.msgs&&d.msgs.length&&!d.endedAt)rpArchiveRecord(id,true);
  const now=new Date(),hh=('0'+now.getHours()).slice(-2),mm=('0'+now.getMinutes()).slice(-2),part=DAYPARTS.indexOf(spec&&spec.daypart)>=0?spec.daypart:dayPartNow();
