function rpSyncArchive(id,rec){for(const cid of rec.memberIds||[id]){const c=getC(cid);if(!c||c.deleted)continue;const rd=rpData(cid);rd.memory=Array.isArray(rd.memory)?rd.memory:[];const i=rd.memory.findIndex(m=>m&&m.id===rec.id);if(i<0)rd.memory.push(JSON.parse(JSON.stringify(rec)));else if(rd.memory[i]!==rec)Object.assign(rd.memory[i],JSON.parse(JSON.stringify(rec)));const summaries=summaryList(c,rec.accountId||'main'),points=rec.points&&rec.points.length?rec.points:[{text:rec.summary,importance:rec.imp||3}];for(let j=summaries.length-1;j>=0;j--)if(summaries[j].roleplayId===rec.id)summaries.splice(j,1);points.forEach((point,index)=>summaries.push({id:rec.id+':'+index,roleplayId:rec.id,roleplayPoint:index,accountId:rec.accountId||'main',text:'【角色扮演游戏回忆·'+rec.title+'】这是一起玩过的虚构剧情，不是现实约会；临时身份不改变真实关系。'+point.text,imp:point.importance||rec.imp||3,ts:rec.ts,time:fmtDate(rec.ts)}));}}
const _rpArchiveBusy=new WeakSet();
async function rpSummarizeArchive(id,rid){const state=S,account=actId(),d=rpData(id),rec=(d.memory||[]).find(m=>m&&m.id===rid);if(!rec||_rpArchiveBusy.has(rec))return;_rpArchiveBusy.add(rec);rec.summaryStatus='working';save();try{const plan=offSummaryPlan(rec.msgs||[]),settings=rpReplySettings(d),mode=rec.summaryMode||settings.summaryMode,raw=await chatAPI([{role:'system',content:'请总结这局角色扮演游戏：你作为参演角色，用第一人称记住一起玩过的虚构背景、参演身份、关键事件、约定和结尾。不能写成现实约会，不编造原文没有的事。'+(mode==='split'?'按重要事件拆成多条重点，每条独立成段。':'整场总结成一条完整记忆。')+'根据原文长度写'+plan.min+'到'+plan.max+'字，直接写正文。'},{role:'user',content:rpHistoryRows(rec.msgs).map(m=>(m.who==='me'?S.me.name:m.who==='旁白'?'旁白':((getC(m.cid||id)||{}).name||'角色'))+'：'+m.text).join('\n')}],Object.assign(rpRequestOptions(id),{aux:settings.summaryModel==='aux',max:plan.tokens,temp:.5,roleInterceptStage:'角色扮演存档总结'})),sum=trimSentence(cleanReply(rpVisibleReplyText(raw)),plan.keep);if(S!==state||actId()!==account||!d.memory.includes(rec))return;if(!sum)throw Error('模型没有返回总结');rec.points=mode==='split'?offSummarySplitPoints(sum,plan):[{text:sum,importance:offSummaryPointImp(sum)}];if(!rec.points.length)rec.points=[{text:sum,importance:3}];rec.summary=rec.points.map(p=>p.text).join('\n');rec.summaryStatus='done';delete rec.summaryError;}catch(e){if(S!==state||actId()!==account||!d.memory.includes(rec))return;rec.summaryStatus='failed';rec.summaryError=offlineReplyFailureReason(e);}finally{_rpArchiveBusy.delete(rec);}if(S!==state||actId()!==account)return;rpSyncArchive(id,rec);save();if(cur().p==='rp'&&cur().id===id)rpRender();}
async function rpManualSummary(id){if(_rp&&_rp.busy){toast('等这一轮说完再总结');return;}const d=rpData(id),state=S,from=Math.max(0,Math.min(d.msgs.length,+d.summaryCursor||0)),part=d.msgs.slice(from);if(!offSummarySourceRows({msgs:part}).length){toast('上次总结后还没有新的对话');return;}if(!await uiConfirm('总结到当前进度？\n总结完成后角色扮演不会结束，可以继续聊天。'))return;if(S!==state)return;const rec=rpArchiveRecord(id,false);if(!rec)return;rec.msgs=rpArchiveRows({msgs:part});rec.summary=part.map(m=>m.text).join('；').slice(0,700);d.summaryCursor=d.msgs.length;rpSyncArchive(id,rec);if(!await saveNowAsync()){toast('原记录仍在，但写入失败，请稍后重试');return;}toast('当前进度已保存，正在后台总结；可以继续聊天');await rpSummarizeArchive(id,rec.id);if(S===state)toast(rec.summaryStatus==='done'?'本段剧情总结已保存':'详细总结暂未完成，原记录和基础记忆仍在');}
async function rpArchiveDelete(id,index){const d=rpData(id),rec=(d.memory||[])[index];if(!rec)return;if(!await uiConfirm('删除这条剧情存档及它的角色记忆副本？不会删除微信消息。',{danger:true}))return;for(const cid of rec.memberIds||[id]){const rd=rpData(cid);rd.memory=(rd.memory||[]).filter(m=>m!==rec&&!(rec.id&&m.id===rec.id));const c=getC(cid);if(c&&rec.id){const list=summaryList(c,rec.accountId||'main');for(let n=list.length-1;n>=0;n--)if(list[n].roleplayId===rec.id)list.splice(n,1);}}save();rpMemory(id,'sum');}
function rpArchiveEdit(id,index){const rec=(rpData(id).memory||[])[index];if(!rec)return;openModal(`<h3>编辑剧情记忆</h3><div class="field"><textarea id="rpa_summary" rows="8">${esc(rec.summary||rec.text||(typeof rec==='string'?rec:''))}</textarea></div><div class="field"><label>重要程度（1～5）</label><input id="rpa_imp" type="number" min="1" max="5" value="${rec.imp||3}"></div><button class="btn p" onclick="rpArchiveSave('${id}',${index})">保存</button><button class="btn g" onclick="rpMemory('${id}','sum')">取消</button>`);}
function rpArchiveSave(id,index){const d=rpData(id),old=d.memory[index],text=($('#rpa_summary').value||'').trim();if(!old||!text)return;if(_rpArchiveBusy.has(old)){toast('正在总结，完成后再编辑');return;}const rec=typeof old==='object'?old:(d.memory[index]={id:uid(),title:'旧剧情',summary:old,accountId:actId(),memberIds:[id],roomId:id});if(!rec.id)rec.id=uid();rec.summary=text;delete rec.points;rec.imp=Math.max(1,Math.min(5,+$('#rpa_imp').value||3));rec.summaryStatus='done';delete rec.summaryError;rpSyncArchive(id,rec);save();rpMemory(id,'sum');}
function rpArchiveView(id,index,back){const rec=(rpData(id).memory||[])[index];if(!rec)return;const tab=back==='saves'?'saves':'sum';openModal(`<h3>${esc(rec.title||'本次剧情')} · 完整记录</h3><div class="hint">角色扮演存档，只读</div>${(rec.msgs||[]).map(m=>`<p><b>${esc(m.who==='me'?S.me.name:m.who==='旁白'?'旁白':((getC(m.cid||id)||{}).remark||(getC(m.cid||id)||{}).name||'角色'))}</b><br>${esc(m.text)}</p>`).join('')||'<div class="hint">这份旧存档只保存了摘要，未包含原文。</div>'}<button class="btn g" onclick="rpMemory('${id}','${tab}')">返回</button>`);}
/* ROLEPLAY_SAVE_SLOTS_V1：剧情存档窗口分两页。「存档」= 一局局的聊天（正在玩 / 已暂停 / 已结束），「总结」= 记忆（d.memory，长的可收起） */
let _rpMemTab='saves';
function rpSumToggle(btn){const p=btn&&btn.previousElementSibling;if(!p)return;const open=p.getAttribute('data-open')==='1';p.setAttribute('data-open',open?'0':'1');p.style.display=open?'-webkit-box':'block';btn.textContent=open?'展开':'收起';}
function rpMemoryTabs(id,tab){const b=(k,label)=>`<button class="btn ${tab===k?'p':'g'}" style="flex:1;margin:0" aria-pressed="${tab===k}" onclick="rpMemory('${id}','${k}')">${label}</button>`;return `<div class="rp-mem-tabs" style="display:flex;gap:8px;margin:10px 0">${b('saves','存档')}${b('sum','总结')}</div>`;}
function rpMemorySaves(id){const d=rpData(id),list=rpSaves(id),j=rpStudioId(id),paused=list.filter(s=>s&&!s.ended),ended=list.filter(s=>s&&s.ended),seen=new Set(list.map(s=>s&&s.session).filter(Boolean)),older=(d.memory||[]).map((m,i)=>({m,i})).filter(x=>x.m&&typeof x.m==='object'&&/_end$/.test(String(x.m.id||''))&&Array.isArray(x.m.msgs)&&x.m.msgs.length&&!seen.has(x.m.session));
  const olderCards=older.map(x=>`<article class="rp-save-card" style="padding:14px;border:1px solid #ffffff24;border-radius:14px;margin:12px 0;overflow-wrap:anywhere;opacity:.85"><header style="display:flex;gap:8px;align-items:center"><b style="flex:1;min-width:0">${esc(x.m.title||'本次剧情')}</b><small style="opacity:.8">已结束</small></header><small style="display:block;opacity:.65;margin-top:4px">${esc(x.m.when||'')} · 共 ${x.m.msgs.length} 条</small><div class="btns" style="margin-top:10px"><button class="btn g" onclick="rpArchiveView('${id}',${x.i},'saves')">查看聊天</button></div></article>`).join('');
  const head=t=>`<h4 style="margin:16px 0 4px;opacity:.8">${t}</h4>`;
  return `<div class="hint">存档是一局局的剧情聊天。没结束的可以读取接着玩；新开一局不会结束正在玩的那局。</div>${d.active||paused.length?head('没结束的')+(d.active?rpSaveCard(id,d,true):'')+paused.map(s=>rpSaveCard(id,s,false)).join(''):''}${ended.length||older.length?head('已结束的')+ended.map(s=>rpSaveCard(id,s,false)).join('')+olderCards:''}${!d.active&&!list.length&&!older.length?'<div class="empty">还没有存档</div>':''}<button class="btn p" style="margin-top:8px" onclick="rpNewGame(${j})">新开一局</button>`;}
function rpMemorySummaries(id){const d=rpData(id),x=rpReplySettings(d);return `${memorySearchBox('搜索剧情总结')}<div class="hint">总结是角色记得的内容，会同时写进他的记忆总结。点顶上「总结」按钮存的、换局或结束时存的都在这里。</div><div class="it" style="margin-bottom:8px"><span>记忆总结模型</span><select onchange="rpSettingSet('${id}','summaryModel',this.value);rpMemory('${id}','sum')" style="background:#24211e;border:1px solid #4b4239;color:#e6ddd3;border-radius:6px;padding:5px"><option value="main" ${x.summaryModel==='main'?'selected':''}>主模型</option><option value="aux" ${x.summaryModel==='aux'?'selected':''}>副模型</option></select></div><div class="it" style="margin-bottom:8px"><span>默认总结方式<small style="display:block;color:#8f8175">不分段=整场一条；分段=拆成多条重点</small></span><select onchange="rpSettingSet('${id}','summaryMode',this.value);rpMemory('${id}','sum')" style="background:#24211e;border:1px solid #4b4239;color:#e6ddd3;border-radius:6px;padding:5px"><option value="single" ${x.summaryMode==='single'?'selected':''}>不分段 · 一整条</option><option value="split" ${x.summaryMode==='split'?'selected':''}>分段 · 多条重点</option></select></div><div class="rp-archive-list">${(d.memory||[]).map((m,i)=>{const text=String(m.summary||m.text||(typeof m==='string'?m:'')),long=text.length>90;return `<article data-memory-row class="rp-archive-card" style="padding:14px;border:1px solid #ffffff24;border-radius:14px;margin:12px 0;overflow-wrap:anywhere"><header style="display:flex;gap:8px;align-items:center;flex-wrap:wrap"><b style="flex:1;min-width:90px">${esc(m.title||'本次剧情')}</b><button class="minibtn" onclick="rpArchiveEdit('${id}',${i})">编辑</button><button class="minibtn" onclick="rpArchiveDelete('${id}',${i})">删除</button></header><small>${esc(m.when||'')}</small><p class="rp-sum-text" data-open="0" style="white-space:pre-wrap;${long?'display:-webkit-box;-webkit-line-clamp:4;-webkit-box-orient:vertical;overflow:hidden':''}">${esc(text)}</p>${long?'<button class="minibtn rp-sum-toggle" onclick="rpSumToggle(this)">展开</button>':''}${m.summaryStatus&&m.summaryStatus!=='done'?`<p class="hint">${m.summaryStatus==='working'?'详细总结尚未完成，原记录已保存，可重试。':esc(m.summaryError||'已保存基础摘要和原记录。')}</p>`:''}${m.msgs?`<button class="minibtn" onclick="rpArchiveView('${id}',${i})">完整记录</button><button class="minibtn" onclick="rpRetrySummary('${id}',${i},'single')">整场一条</button><button class="minibtn" onclick="rpRetrySummary('${id}',${i},'split')">拆成多条</button>`:''}</article>`;}).join('')||'<div class="empty">还没有总结</div>'}</div>`;}
function rpMemory(id,tab){const c=getC(id);_rpMemTab=tab==='sum'?'sum':'saves';rpStudioModal(`<h3>${esc(c&&(c.remark||c.name)||'角色')} 的剧情存档</h3>${rpMemoryTabs(id,_rpMemTab)}${_rpMemTab==='sum'?rpMemorySummaries(id):rpMemorySaves(id)}<button class="btn g" style="margin-top:8px" onclick="closeModal()">关闭</button>`);}
function rpRetrySummary(id,index,mode){const rec=(rpData(id).memory||[])[index];if(!rec)return;if(mode)rec.summaryMode=mode;rpSummarizeArchive(id,rec.id);closeModal();toast('原记录已保留，正在重新总结');}
/* ROLEPLAY_END_MESSAGE_V1: after durable archive, resume real WeChat once per story. */
function rpArchiveFallback(id,rows){return rpHistoryRows(rows).map(m=>(m.who==='me'?S.me.name:m.who==='旁白'?'旁白':(getC(m.cid||id)||{}).name||'角色')+'：'+m.text).join('；').slice(0,700);}
/* ROLEPLAY_SAVE_SLOTS_V1：结束时只把上次存进记忆之后的新内容存成记忆，存过的不再重复；整局聊天移到「存档」页的已结束里 */
async function rpEnd(id){const d=rpData(id);if(_rp&&_rp.id===id&&_rp.busy){toast('等这一轮说完再结束');return;}if(!d.active)return;const state=S,account=actId(),session=d.session,started=d.startedAt;if(!await uiConfirm('结束这局角色扮演？\n上次存进记忆之后的新内容会存进记忆，整局聊天留在「剧情存档 → 存档」里可以查看。'))return;if(S!==state||actId()!==account||d.session!==session||d.startedAt!==started||!d.active)return;
  const list=d.msgs||[],prevCursor=+d.summaryCursor||0,from=Math.max(0,Math.min(list.length,prevCursor)),part=rpArchiveRows({msgs:list.slice(from)}),hasNew=rpHistoryRows(part).some(m=>String(m.text||'').trim());let rec=null;
  if(hasNew){const key=d.session||(d.session='rp_'+(d.startedAt||Date.now())+'_'+uid()),existed=(d.memory||[]).some(m=>m&&m.id===key+'_end');rec=rpArchiveRecord(id,true);if(rec&&!existed){rec.msgs=part;rec.summary=rpArchiveFallback(id,part);rpSyncArchive(id,rec);}d.summaryCursor=list.length;}
  const notify=!!list.length&&!(d.session&&d.endNotified===d.session)&&!(rec&&rec.afterMessageRequested),wasActive=d.active,title=d.title||'本次剧情',hisRole=rpMemberSummary(id),meRole=d.myRole||S.me.name,memberIds=rec&&rec.memberIds||rpMembers(id).map(m=>m.id),closing=rpHistoryRows(rpArchiveRows(d)).slice(-10).map(m=>(m.who==='me'?S.me.name:m.who==='旁白'?'旁白':((getC(m.cid||id)||{}).remark||(getC(m.cid||id)||{}).name||'角色'))+'：'+m.text).join('\n').slice(-2200);
  if(notify){d.endNotified=d.session;if(rec)rec.afterMessageRequested=true;}d.active=false;d.endedAt=Date.now();d.summary=rec?rec.summary:(d.summary||'');const mids=Object.assign({},d.inviteMids||{});if(d.inviteMid)mids[id]=d.inviteMid;for(const cid of Object.keys(mids)){const m=msgs(cid).find(x=>x.id===mids[cid]);if(m){m.active=false;m.finished=true;m.summary=d.summary;}}
  if(!await saveNowAsync()){d.active=wasActive;d.endedAt=0;d.summaryCursor=prevCursor;if(notify){delete d.endNotified;if(rec)rec.afterMessageRequested=false;}toast('剧情仍在当前页面，但写入失败，请重试保存');return;}if(S!==state||actId()!==account)return;
  rpParkEnded(id);save();_rp=null;_rpSel=null;toast(rec?'这局已结束，新内容已存进记忆':'这局已结束');go('rphub');
  if(notify){for(const cid of memberIds||[id]){const c=getC(cid);if(!c||c.deleted||c.blocked)continue;scheduleReply(cid,'[系统：你和'+S.me.name+'刚结束手机角色扮演软件里的《'+title+'》这局游戏，完整剧情已经保留。现在回到普通微信，以你平时真实自己的身份主动给ta发一条自然的消息，承接刚才一起玩的内容，说感受、逗ta、关心ta或聊下一次。不要只说“结束了”“存档成功”，不要变成机械通知。你记得这是一起玩过的虚构剧情，临时扮演身份不是现实身份，游戏事件不能当成现实约会，也不要自动开新局。请根据原记录自然发挥，不要照抄系统提示。\n本局身份：'+hisRole+'；'+S.me.name+'扮演：'+meRole+'。\n本局收尾原文：\n'+closing+']');}}if(rec)rpSummarizeArchive(id,rec.id);}
